import type { T } from "../i18n";
import type { ReadKind, ReadPiece } from "./dramaReadings";

/**
 * 朗读 · 中英通用: pieces about things every table knows (the Wi-Fi, Fridays, the alarm clock, the
 * cat, the printer, the flat-pack wardrobe, the parking lot; and played straight, the morning train,
 * a golden wedding, parents, a friend far away, yourself ten years ago), written to land in Chinese
 * and in English alike; where a detail only works in one place (a city, a price), each language has
 * its own.
 */

const t = (zh: string, en: string): T => ({ zh, en });
const p = (id: string, kind: ReadKind, title: T, how: T, lines: T[]): ReadPiece => ({ id, set: "both", kind, level: "all", title, how, lines });

